// LLD: inside the URL Shortener service.
// Strategy pattern lets us swap the encoding algorithm
// without touching the service that uses it.

class KeyGenerationStrategy {
  generate(counter) {
    throw new Error('generate() must be implemented');
  }
}

class Base62Strategy extends KeyGenerationStrategy {
  constructor() {
    super();
    this.alphabet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  }
  generate(counter) {
    let n = counter, key = '';
    const base = this.alphabet.length;
    while (n > 0) {
      key = this.alphabet[n % base] + key;
      n = Math.floor(n / base);
    }
    return key.padStart(6, 'a');
  }
}

// Repository pattern hides the storage engine behind an interface.
class UrlRepository {
  save(shortKey, longUrl) { throw new Error('not implemented'); }
  find(shortKey) { throw new Error('not implemented'); }
}

class InMemoryUrlRepository extends UrlRepository {
  constructor() {
    super();
    this.store = new Map();
  }
  save(shortKey, longUrl) { this.store.set(shortKey, longUrl); }
  find(shortKey) { return this.store.get(shortKey) || null; }
}

class UrlShortenerService {
  constructor(keyStrategy, repository) {
    this.keyStrategy = keyStrategy;
    this.repository = repository;
    this.counter = 1000;
  }
  shorten(longUrl) {
    const shortKey = this.keyStrategy.generate(this.counter++);
    this.repository.save(shortKey, longUrl);
    return shortKey;
  }
  resolve(shortKey) {
    const longUrl = this.repository.find(shortKey);
    if (!longUrl) throw new Error('Short URL not found');
    return longUrl;
  }
}

const service = new UrlShortenerService(new Base62Strategy(), new InMemoryUrlRepository());
const key = service.shorten('https://algorithmxlr8.io/dsa/graphs');
console.log('short key:', key);
console.log('resolved:', service.resolve(key));

