# LLD: inside the URL Shortener service.
# Strategy pattern lets us swap the encoding algorithm
# without touching the service that uses it.
from abc import ABC, abstractmethod


class KeyGenerationStrategy(ABC):
    @abstractmethod
    def generate(self, counter: int) -> str:
        raise NotImplementedError


class Base62Strategy(KeyGenerationStrategy):
    ALPHABET = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"

    def generate(self, counter: int) -> str:
        n, key = counter, ""
        base = len(self.ALPHABET)
        while n > 0:
            key = self.ALPHABET[n % base] + key
            n //= base
        return key.rjust(6, "a")


class UrlRepository(ABC):
    @abstractmethod
    def save(self, short_key: str, long_url: str) -> None: ...

    @abstractmethod
    def find(self, short_key: str) -> str: ...


class InMemoryUrlRepository(UrlRepository):
    def __init__(self):
        self.store = {}

    def save(self, short_key: str, long_url: str) -> None:
        self.store[short_key] = long_url

    def find(self, short_key: str) -> str:
        return self.store.get(short_key)


class UrlShortenerService:
    def __init__(self, key_strategy: KeyGenerationStrategy, repository: UrlRepository):
        self.key_strategy = key_strategy
        self.repository = repository
        self.counter = 1000

    def shorten(self, long_url: str) -> str:
        short_key = self.key_strategy.generate(self.counter)
        self.counter += 1
        self.repository.save(short_key, long_url)
        return short_key

    def resolve(self, short_key: str) -> str:
        long_url = self.repository.find(short_key)
        if not long_url:
            raise ValueError("Short URL not found")
        return long_url


service = UrlShortenerService(Base62Strategy(), InMemoryUrlRepository())
key = service.shorten("https://algorithmxlr8.io/dsa/graphs")
print("short key:", key)
print("resolved:", service.resolve(key))

