#include <bits/stdc++.h>
using namespace std;

class KeyGenerationStrategy {
public:
    virtual string generate(long long counter) = 0;
    virtual ~KeyGenerationStrategy() = default;
};

class Base62Strategy : public KeyGenerationStrategy {
    string alphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
public:
    string generate(long long counter) override {
        long long n = counter;
        string key;
        int base = alphabet.size();
        while (n > 0) {
            key = alphabet[n % base] + key;
            n /= base;
        }
        while (key.size() < 6) key = "a" + key;
        return key;
    }
};

class UrlRepository {
public:
    virtual void save(const string& shortKey, const string& longUrl) = 0;
    virtual string find(const string& shortKey) = 0;
    virtual ~UrlRepository() = default;
};

class InMemoryUrlRepository : public UrlRepository {
    map<string, string> store;
public:
    void save(const string& shortKey, const string& longUrl) override {
        store[shortKey] = longUrl;
    }

    string find(const string& shortKey) override {
        auto it = store.find(shortKey);
        return it != store.end() ? it->second : "";
    }
};

class UrlShortenerService {
    KeyGenerationStrategy& keyStrategy;
    UrlRepository& repository;
    long long counter = 1000;
public:
    UrlShortenerService(KeyGenerationStrategy& keyStrategy, UrlRepository& repository)
        : keyStrategy(keyStrategy), repository(repository) {}

    string shorten(const string& longUrl) {
        string shortKey = keyStrategy.generate(counter++);
        repository.save(shortKey, longUrl);
        return shortKey;
    }

    string resolve(const string& shortKey) {
        string longUrl = repository.find(shortKey);
        if (longUrl.empty()) throw runtime_error("Short URL not found");
        return longUrl;
    }
};

int main() {
    Base62Strategy strategy;
    InMemoryUrlRepository repository;
    UrlShortenerService service(strategy, repository);

    string key = service.shorten("https://algorithmxlr8.io/dsa/graphs");
    cout << "short key: " << key << endl;
    cout << "resolved: " << service.resolve(key) << endl;

    return 0;
}

