// LLD: Observer pattern inside a NotificationService.
// Adding a new channel means adding a class, not editing existing ones.
import java.util.ArrayList;
import java.util.List;

interface NotificationChannel {
    void send(String userId, String message);
}

class EmailChannel implements NotificationChannel {
    public void send(String userId, String message) {
        System.out.println("email to " + userId + ": " + message);
    }
}

class SmsChannel implements NotificationChannel {
    public void send(String userId, String message) {
        System.out.println("sms to " + userId + ": " + message);
    }
}

class NotificationService {
    private final List<NotificationChannel> channels = new ArrayList<>();

    public void subscribe(NotificationChannel channel) { channels.add(channel); }

    public void notify(String userId, String message) {
        for (NotificationChannel channel : channels) channel.send(userId, message);
    }
}

public class Main {
    public static void main(String[] args) {
        NotificationService notifications = new NotificationService();
        notifications.subscribe(new EmailChannel());
        notifications.subscribe(new SmsChannel());
        notifications.notify("user_42", "Your order has shipped");
        // Adding WhatsApp later: notifications.subscribe(new WhatsAppChannel())
    }
}

