class NotificationChannel {
public:
    virtual void send(const string& userId, const string& message) = 0;
    virtual ~NotificationChannel() = default;
};

class EmailChannel : public NotificationChannel {
public:
    void send(const string& userId, const string& message) override {
        cout << "email to " << userId << ": " << message << endl;
    }
};

class SmsChannel : public NotificationChannel {
public:
    void send(const string& userId, const string& message) override {
        cout << "sms to " << userId << ": " << message << endl;
    }
};

class NotificationService {
    vector<NotificationChannel*> channels;
public:
    void subscribe(NotificationChannel* channel) { channels.push_back(channel); }

    void notify(const string& userId, const string& message) {
        for (auto channel : channels) channel->send(userId, message);
    }
};

int main() {
    NotificationService notifications;
    EmailChannel email;
    SmsChannel sms;
    notifications.subscribe(&email);
    notifications.subscribe(&sms);
    notifications.notify("user_42", "Your order has shipped");
    // Adding WhatsApp later: notifications.subscribe(new WhatsAppChannel())

    return 0;
